import sys
from functools import lru_cache
sys.setrecursionlimit(10000)
data = sys.stdin.read().split()
n = int(data[0]); pos = 1
suspects = []
for i in range(n):
    k = int(data[pos]); pos += 1
    suspects.append(set(int(v) for v in data[pos:pos + k])); pos += k
@lru_cache(maxsize=None)
def ways(remaining):
    if len(remaining) == 1:
        return 1
    total = 0
    for seat in remaining:
        accusers = sum(1 for other in remaining if other != seat and seat in suspects[other - 1])
        if 2 * accusers > len(remaining) - 1:
            total += ways(remaining - frozenset([seat]))
    return total
print(ways(frozenset(range(1, n + 1))))
